html:details.fr:tex:
\begin {align*}
  q_{\pi }(s, a) = \sum _{s', r} p(s', r \mid  s, a) \big (r + \gamma  v_{\pi }(s')\big )
\end {align*}

html:div.style:
margin: 1em 0 1em 0.25em;
padding: 0.5em 1.1em 0.5em 1.2em;
